package com.projectdark.mobile;
import static org.junit.Assert.*;
import android.content.*;import android.graphics.*;import com.projectdark.mobile.world.*;import java.util.*;import java.io.*;import java.lang.reflect.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=34,manifest=Config.NONE) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class PortalServicesV248Test {
 Context c;MineTownV203Test f;
 @Before public void setup(){f=new MineTownV203Test();f.reset();c=RuntimeEnvironment.getApplication();}
 static void save(Bitmap b,String name)throws Exception{File p=new File("build/reports/horror-v179/v248/"+name+".png");p.getParentFile().mkdirs();try(FileOutputStream o=new FileOutputStream(p)){assertTrue(b.compress(Bitmap.CompressFormat.PNG,100,o));}}
 static int[] pixels(Bitmap b){int[] p=new int[b.getWidth()*b.getHeight()];b.getPixels(p,0,b.getWidth(),0,0,b.getWidth(),b.getHeight());return p;}
 void shot(GameView v,String name)throws Exception{Bitmap b=Bitmap.createBitmap(960,540,Bitmap.Config.ARGB_8888);v.draw(new Canvas(b));save(b,name);b.recycle();}
 @Test public void presentAndFutureServiceAndTransportRolesUseFullExactOriginalPixels()throws Exception{
  Set<String> ids=new LinkedHashSet<>();for(TownInteriorDef d:TownServicesV247Test.rooms())if(d.kind==TownInteriorDef.Kind.REAGENT||d.kind==TownInteriorDef.Kind.BANK)ids.add(d.npcId);for(NpcIdentity.Profile p:NpcIdentity.ALL)if(TownTravel.isManager(p.id))ids.add(p.id);ids.add(HorrorCastleTravel.EXIT_NPC);ids.add("death_reagent_knight");TownServiceArt.register("future_reagent_248","REAGENT");TownServiceArt.register("future_bank_248","BANK");ids.add("future_reagent_248");ids.add("future_bank_248");NpcActorRenderer actors=new NpcActorRenderer(c);int row=0;Bitmap roster=Bitmap.createBitmap(800,((ids.size()+5)/6)*150,Bitmap.Config.ARGB_8888);Canvas rc=new Canvas(roster);rc.drawColor(0xff352e24);Paint label=new Paint();label.setColor(Color.WHITE);label.setTextSize(10);
  for(String id:ids){String role=TownServiceArt.role(id);assertNotNull(id,role);if(TownTravel.isManager(id))assertEquals("백원만",NpcIdentity.forId(id).name);Bitmap expected=Bitmap.createBitmap(160,160,Bitmap.Config.ARGB_8888),actual=Bitmap.createBitmap(160,160,Bitmap.Config.ARGB_8888);Bitmap src;try(InputStream in=c.getAssets().open("town-v248/"+role+".png")){src=BitmapFactory.decodeStream(in);}Paint nearest=new Paint();nearest.setFilterBitmap(false);new Canvas(expected).drawBitmap(src,80-src.getWidth()/2f,140-src.getHeight(),nearest);actors.draw(new Canvas(actual),id,80,140,CharacterRenderer.Direction.NE,CharacterRenderer.State.ATTACK,55);assertArrayEquals(id,pixels(expected),pixels(actual));assertTrue(TownServiceArt.labelOffset(id)>=src.getHeight()+8);int x=row%6*133,y=row/6*150;rc.drawBitmap(actual,x-15,y-5,null);rc.drawText(id,x+2,y+145,label);row++;src.recycle();expected.recycle();actual.recycle();}
  assertEquals(20,ids.size());save(roster,"all-source-npc-roles");roster.recycle();
 }
 @Test public void allSeventyOneActualMapsDrawSharedAnimatedGroupsAndReuseFloorCaches()throws Exception{
  AllMapLabelsV246Test fixture=new AllMapLabelsV246Test();fixture.setup();GameView v=new GameView(c);v.layout(0,0,960,540);RuntimeState s=f.field(v,"state");JSONArray audit=new JSONArray();int pins=0;
  for(String id:AllMapLabelsV246Test.maps()){fixture.enter(v,id);WorldRuntimeAdapter w=(WorldRuntimeAdapter)f.call(v,"activeWorld",new Class<?>[]{});List<WorldMapWindow.Pin> entrances=WorldMapWindow.entrances(id);WorldMapWindow.Pin first=entrances.get(0);s.player().x=first.targetX;s.player().y=first.targetY;w.cancelForAction();w.snapCameraToPlayer();Bitmap a=Bitmap.createBitmap(960,540,Bitmap.Config.ARGB_8888),b=Bitmap.createBitmap(960,540,Bitmap.Config.ARGB_8888);PortalAnimation.time(.75f);int draws=PortalAnimation.mapDraws;v.draw(new Canvas(a));assertEquals(id,draws+1,PortalAnimation.mapDraws);assertEquals(id,PortalAnimation.lastMap);assertEquals(id,entrances.size(),PortalAnimation.lastPins);if(WorldDef.ID.equals(id)){WorldCameraTransform.Point clear=w.worldToScreen(TempleEntranceRenderer.X+32,TempleEntranceRenderer.Y-32);int pixel=a.getPixel(Math.round(clear.x),Math.round(clear.y));assertTrue("old baked white beam must be absent outside the new38px portal",Color.blue(pixel)<90);}PortalAnimation.time(1.75f);v.draw(new Canvas(b));assertFalse(id+" visible original portal colors advance",Arrays.equals(pixels(a),pixels(b)));assertEquals(583680,PortalAnimation.bytes());save(a,"portal-"+id);audit.put(new JSONObject().put("map",id).put("groups",entrances.size()).put("animatedDifference",true));pins+=entrances.size();a.recycle();b.recycle();}
  assertEquals(71,audit.length());assertEquals(130,pins);File file=new File("build/reports/horror-v179/v248/all-portal-audit.json");try(FileOutputStream out=new FileOutputStream(file)){out.write(new JSONObject().put("maps",71).put("groups",pins).put("atlasBytes",PortalAnimation.bytes()).put("records",audit).toString(2).getBytes(java.nio.charset.StandardCharsets.UTF_8));}
  PortalAnimation.time(0);assertEquals(0,PortalAnimation.frame());PortalAnimation.tick(.125f);assertEquals(1,PortalAnimation.frame());PortalAnimation.time(3.875f);assertEquals(31,PortalAnimation.frame());PortalAnimation.tick(.125f);assertEquals(0,PortalAnimation.frame());
 }
 @Test public void deathKnightIsReachableAndSellsRealReagentsAndRecallsThroughSharedShop()throws Exception{
  GameView v=new GameView(c);v.layout(0,0,960,540);RuntimeState s=f.field(v,"state");s.rpg().restoreGold(10000);f.call(v,"travelTown",new Class<?>[]{String.class},DeathVillageGeometry.LOBBY);WorldRuntimeAdapter w=f.field(v,"poteFieldAdapter");RuntimeState.Npc knight=s.npcs().stream().filter(n->n.id.equals("death_reagent_knight")).findFirst().get();assertEquals("death-knight",TownServiceArt.role(knight.id));assertTrue(CampaignNavigationTest.walk(w,w.requestNpcApproach(knight.id)));assertEquals(InteractionController.TickResult.DIALOG_OPENED,((InteractionController)f.field(v,"interaction")).request(s,knight));f.tick(v,2);TownShopWindow shop=f.field(v,"townWindow");assertTrue(shop.isOpen());assertEquals("death_reagent_knight",f.field(shop,"campaignNpc"));shop.guide("IT_RECALL_MILLES",false);shot(v,"death-knight-shop-recall");int before=s.rpg().inventory().getOrDefault("IT_RECALL_MILLES",0);TownInteriorTest.tap(v,761.25f,376.875f);TownInteriorTest.tap(v,671.25f,326.25f);assertEquals(9000,s.rpg().gold().longValue());assertEquals(before+1,s.rpg().inventory().get("IT_RECALL_MILLES").intValue());shop.close();RpgInteractionController inv=f.field(v,"rpgInteraction");inv.selectInventoryItem(s.rpg(),"IT_RECALL_MILLES");f.call(v,"activateInventoryItem",new Class<?>[]{});assertEquals(WorldDef.ID,s.currentMapId());assertEquals(9000,s.rpg().gold().longValue());assertEquals(before,s.rpg().inventory().getOrDefault("IT_RECALL_MILLES",0).intValue());
 }
}
